import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Guild influence","description":"","frontmatter":{"pageId":"players/guild-influence","contentRevision":1},"headers":[],"relativePath":"en/players/guild-influence.md","filePath":"en/players/guild-influence.md"}'),l={name:"en/players/guild-influence.md"};function s(r,e,o,c,d,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="guild-influence" tabindex="-1">Guild influence <a class="header-anchor" href="#guild-influence" aria-label="Permalink to &quot;Guild influence&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Open <strong>Guild influence zones → Settings</strong> on the world map or influence settings in your alliance. Select your home root-surface colony and explicitly publish influence. This reveals alliance name and color, not treasury, membership or chat. Publication is off by default.</p><p>The radius is 3 adjacent land steps; strength is 4 − distance. Water blocks propagation. Contributions from one alliance use their maximum, not their sum; equal strength from different alliances produces neutral hatching. The alliance owner chooses one of 16 colors. Offline sources still count.</p><p>The local overlay toggle does not withdraw consent. Use the separate withdrawal action: it advances consent version even when already unpublished, preventing a delayed enable request.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>This is not ownership, war, outposts or access permission. The server-wide cap is 128 active sources. An over-cap imported database makes the entire overlay unavailable. Reset/leaving/disbanding revokes consent; archive restore rechecks context and capacity. Administrators can disable, not enable on a player&#39;s behalf.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./community">Profiles, friends and alliances</a></li><li><a href="./world">Shared world and settlements</a></li><li><a href="./../admins/api">REST API reference</a></li></ul>',10)])])}const f=a(l,[["render",s]]);export{p as __pageData,f as default};
